-- =============================================================================
-- 0024_seed_catalog.sql
-- Feature: the starting catalogue. Document categories with their guidance,
-- the seven built-in check types (version 1, published), three packages,
-- status wording for staff, clients and candidates, two request templates
-- and the default assignment rules. Everything stays editable in Settings.
-- Generated by scripts/gen-catalog-seed.ts from src/domain/check-types/builtin.ts;
-- tests/unit/check-types.test.ts checks the two match. Idempotent.
-- Package prices start at 0: set them in Settings → Packages.
-- Depends on: 0004_check_types, 0005_packages_templates, 0006_cases, 0016_assignment.
-- =============================================================================

-- Document categories
insert into public.document_categories (org_id, key, name, guide, sensitive, sort)
select o.id, x.key, x.name, x.guide, x.sensitive, x.sort
  from public.orgs o
 cross join jsonb_to_recordset($categories$[
  {
    "key": "cv",
    "name": "CV / résumé",
    "guide": "The candidate's latest CV, as a PDF or a clear photo of each page.",
    "sensitive": false,
    "sort": 10
  },
  {
    "key": "consent_form",
    "name": "Signed consent form",
    "guide": "The consent and authorisation form, signed by the candidate. A clear photo of the signed page is fine.",
    "sensitive": false,
    "sort": 20
  },
  {
    "key": "nic_copy",
    "name": "NIC copy",
    "guide": "Both sides of the National Identity Card, readable and uncropped.",
    "sensitive": false,
    "sort": 30
  },
  {
    "key": "education_certificate",
    "name": "Education certificate",
    "guide": "O/L, A/L, diploma or degree certificates. Upload each certificate separately.",
    "sensitive": false,
    "sort": 40
  },
  {
    "key": "transcript",
    "name": "Academic transcript",
    "guide": "The transcript or results sheet issued by the institution, if available.",
    "sensitive": false,
    "sort": 50
  },
  {
    "key": "service_letter",
    "name": "Service letter",
    "guide": "A service or experience letter from each previous employer.",
    "sensitive": false,
    "sort": 60
  },
  {
    "key": "resignation_letter",
    "name": "Resignation and acceptance letters",
    "guide": "The resignation letter and the employer's acceptance, if you have them.",
    "sensitive": false,
    "sort": 70
  },
  {
    "key": "gn_certificate",
    "name": "Grama Niladhari certificate",
    "guide": "The residence certificate issued by your Grama Niladhari.",
    "sensitive": false,
    "sort": 80
  },
  {
    "key": "field_verification",
    "name": "Field verification record",
    "guide": "Photos and notes from the address visit (Ontriq staff).",
    "sensitive": false,
    "sort": 90
  },
  {
    "key": "police_report",
    "name": "Police clearance report",
    "guide": "The police clearance report or the station's confirmation.",
    "sensitive": true,
    "sort": 100
  },
  {
    "key": "reference_form",
    "name": "Reference form",
    "guide": "Completed reference forms or written feedback from referees.",
    "sensitive": false,
    "sort": 110
  },
  {
    "key": "sanction_report",
    "name": "Global sanction screening report",
    "guide": "The screening platform's report (for example Cfirst), attached to the final report unchanged.",
    "sensitive": true,
    "sort": 120
  },
  {
    "key": "other",
    "name": "Other document",
    "guide": "Anything else that supports a check.",
    "sensitive": false,
    "sort": 999
  }
]$categories$::jsonb)
       as x(key text, name text, guide text, sensitive boolean, sort int)
on conflict (org_id, key) do nothing;

